// ─────────────────────────────────────────
// Update order status (admin)
// ─────────────────────────────────────────
export const updateOrderStatus = async (orderId, status, adminNotes = null, estimatedDelivery = null) => {
  try {
    const updates = { status };
    if (adminNotes !== null) updates.admin_notes = adminNotes;
    if (estimatedDelivery !== null) updates.estimated_delivery = estimatedDelivery;

    const { data, error } = await supabase
      .from('orders')
      .update(updates)
      .eq('id', orderId)
      .select()
      .single();

    if (error) throw error;
    return { data, error: null };
  } catch (error) {
    return { data: null, error };
  }
};
